// Reproducible Android project setup (shared by every game; run from the game's root). android/ is gitignored (generated by
// `cap add android`), so everything custom about it lives in tracked files:
//   config/android/overlay/        MainActivity, manifest (AdMob app ID), strings, launcher icons
//   config/android/<env>/          per-Firebase-project google-services.json
//   this script                    release signing block + versionCode/versionName from package.json
//
//   node node_modules/@gamebase/gbengine/scripts/android-config.mjs <dev|prod> [--build]
//
// Creates android/ if missing, applies the overlay + env config, and (with
// --build) runs gradle bundleRelease/assembleRelease. Run the web build and
// `npx cap sync android` yourself first (see the android:* scripts in package.json).
// Release signing reads android/keystore.properties, which is never committed —
// copy config/android/keystore.properties.example and fill it in.
import { cpSync, copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';

const env = process.argv[2];
const build = process.argv.includes('--build');
const services = `config/android/${env}/google-services.json`;
if (!existsSync(services)) {
    console.error(`Usage: node node_modules/@gamebase/gbengine/scripts/android-config.mjs <dev|prod> [--build]  (missing ${services})`);
    process.exit(1);
}

const run = (cmd, args, opts = {}) => {
    const r = spawnSync(cmd, args, { stdio: 'inherit', shell: true, ...opts });
    if (r.status !== 0) { console.error(`\`${cmd} ${args.join(' ')}\` failed`); process.exit(r.status ?? 1); }
};

// 1. Generate the native project the first time.
if (!existsSync('android/app')) {
    // cap add insists on a web dir with an index.html; the real build replaces this placeholder.
    if (!existsSync('dist/index.html')) {
        mkdirSync('dist', { recursive: true });
        writeFileSync('dist/index.html', '<!doctype html><title>placeholder</title>');
    }
    const r = spawnSync('npx', ['cap', 'add', 'android'], { stdio: 'inherit', shell: true });
    if (r.status !== 0) {
        rmSync('android', { recursive: true, force: true }); // don't leave a half-made project that looks finished
        console.error('`npx cap add android` failed');
        process.exit(r.status ?? 1);
    }
}

// 2. Overlay tracked customizations, then the env's Firebase config.
cpSync('config/android/overlay', 'android', { recursive: true });
copyFileSync(services, 'android/app/google-services.json');

// 3. app/build.gradle: release signing + version from package.json.
const { version } = JSON.parse(readFileSync('package.json', 'utf8'));
const [maj, min, pat] = version.split('.').map(Number);
const versionCode = maj * 10000 + min * 100 + pat; // matches bump-version.js's +1 per patch
const gradlePath = 'android/app/build.gradle';
let gradle = readFileSync(gradlePath, 'utf8');
if (!gradle.includes('keystore.properties')) {
    gradle = gradle
        .replace("apply plugin: 'com.android.application'\n", `apply plugin: 'com.android.application'

def keystorePropertiesFile = rootProject.file('keystore.properties')
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}
`)
        .replace(/(\n\s*)buildTypes \{/, `$1signingConfigs {
        release {
            if (keystorePropertiesFile.exists()) {
                storeFile file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
            }
        }
    }
    buildTypes {`)
        .replace(/(proguardFiles [^\n]*\n)/, `$1            signingConfig signingConfigs.release\n`);
}
gradle = gradle
    .replace(/versionCode\s+\d+/, `versionCode ${versionCode}`)
    .replace(/versionName\s+"[^"]*"/, `versionName "${version}"`);
writeFileSync(gradlePath, gradle);
console.log(`android/ configured for ${env}: ${version} (versionCode ${versionCode})`);

// Gradle needs the SDK path; Android Studio normally writes this file.
if (!existsSync('android/local.properties')) {
    const sdk = process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT
        || (process.env.LOCALAPPDATA && join(process.env.LOCALAPPDATA, 'Android', 'Sdk'));
    if (sdk && existsSync(sdk)) {
        writeFileSync('android/local.properties', `sdk.dir=${sdk.replace(/\\/g, '/')}\n`);
    } else {
        console.warn('WARNING: Android SDK not found — set ANDROID_HOME or create android/local.properties (sdk.dir=...)');
    }
}

if (env === 'prod' && !existsSync('android/keystore.properties')) {
    console.warn('WARNING: android/keystore.properties missing — release builds will be unsigned. See config/android/keystore.properties.example');
}

// 4. Optional release build. Capacitor 8 needs JDK 21+; prefer the newest installed.
if (build) {
    if (!existsSync('android/keystore.properties')) {
        console.error('Cannot sign the release build: android/keystore.properties is missing.');
        process.exit(1);
    }
    const jdkRoot = 'C:/Program Files/Java';
    const jdks = existsSync(jdkRoot)
        ? readdirSync(jdkRoot).map(d => ({ d, n: Number(/^jdk-?(\d+)/.exec(d)?.[1]) })).filter(j => j.n >= 21).sort((a, b) => b.n - a.n)
        : [];
    const javaHome = process.env.ANDROID_JAVA_HOME || (jdks[0] && join(jdkRoot, jdks[0].d));
    const gradlew = process.platform === 'win32' ? '.\\gradlew.bat' : './gradlew';
    run(gradlew, ['bundleRelease', 'assembleRelease'], {
        cwd: 'android',
        env: { ...process.env, ...(javaHome ? { JAVA_HOME: javaHome } : {}) },
    });
}
